// Some portions generated by Codex

const test = require('node:test');
const assert = require('node:assert/strict');
const { MemoryWorker, loadApi } = require('./query-load-more-harness.js');

class UnavailableWorker extends MemoryWorker {
    postMessage(message) {
        queueMicrotask(() => {
            const response = { requestId: message.requestId, ok: false, unavailable: true,
                error: 'IndexedDB is unavailable for Workbench query results.' };
            for (const listener of this.listeners.get('message') || []) listener({ data: response });
        });
    }
}

test('page row stores share one memory budget and release reservations on disposal', async () => {
    const { api } = loadApi();
    const budget = api.createRowStoreBudget(4000);
    const options = { memoryBudget: budget, workerFactory: () => new UnavailableWorker(), spillRowLimit: 0,
        storageTimeout: 100 };
    const first = await api.createRowStore(options);
    const second = await api.createRowStore(options);
    const rows = [[{ kind: 'literal', value: 'x'.repeat(1300) }]];
    await first.append(rows);
    for (let i = 0; i < 10; i++) await new Promise(resolve => setImmediate(resolve));
    assert.ok(budget.usedBytes > 0 && budget.usedBytes <= budget.maxBytes);
    await assert.rejects(second.append(rows), /memory|storage|budget/i);
    assert.equal(await first.count(), 1);
    assert.equal(await second.count(), 0);
    await first.dispose();
    assert.equal(await second.append(rows), 1, 'disposing the first store releases its reservation');
    await second.dispose();
    assert.equal(budget.usedBytes, 0, 'disposing every store releases the shared budget');
});

test('a failed pressure handler is reported after every handler runs and releases no bytes twice', async () => {
    const { api } = loadApi();
    const budget = api.createRowStoreBudget(1024);
    const retained = budget.createReservation('retained');
    const waiting = budget.createReservation('temporary');
    await retained.grow(512);

    const failure = new Error('pressure move failed');
    let ownerFailure;
    let laterHandlerRan = false;
    const unregisterFailed = budget.registerPressureHandler(() => { throw failure; }, error => {
        ownerFailure = error;
    });
    const unregisterLater = budget.registerPressureHandler(() => { laterHandlerRan = true; });

    await assert.rejects(waiting.grow(600, 20), error => error === failure);
    assert.equal(ownerFailure, failure, 'the store that failed its spill records the cause');
    assert.equal(laterHandlerRan, true, 'one failed spill does not skip other stores');
    assert.equal(budget.usedBytes, 512, 'the rejected request did not leak a reservation');

    unregisterFailed();
    unregisterLater();
    waiting.release();
    retained.release();
    assert.equal(budget.usedBytes, 0);
});

test('worker row reads reserve their decoded window before asking the worker', async () => {
    const { api, json } = loadApi();
    const budget = api.createRowStoreBudget(20000);
    const workers = [];
    const store = await api.createRowStore({ memoryBudget: budget, workerFactory() {
        const worker = new MemoryWorker();
        workers.push(worker);
        return worker;
    }, spillRowLimit: 0, storageTimeout: 20 });

    await store.append([[{ kind: 'literal', value: 'x'.repeat(1500) }]]);
    for (let attempt = 0; store.inMemory && attempt < 20; attempt++) {
        await new Promise(resolve => setImmediate(resolve));
    }
    assert.equal(store.inMemory, false, 'the row is stored in the worker before testing a read');
    const blocker = budget.createReservation('temporary');
    await blocker.grow(8000);
    const usedBeforeRead = budget.usedBytes;

    await assert.rejects(store.read(0, 1), /budget|storage/i);
    assert.equal(workers[0].messages.some(message => message.op === 'read'), false,
        'an oversized window is rejected before transferring or parsing its text');
    assert.equal(budget.usedBytes, usedBeforeRead, 'failed reads release their temporary reservation');

    blocker.release();
    const worker = workers[0];
    const postMessage = worker.postMessage.bind(worker);
    worker.postMessage = message => {
        if (message.op !== 'read') {
            postMessage(message);
            return;
        }
        worker.messages.push(message);
        queueMicrotask(() => {
            const response = { requestId: message.requestId, ok: true,
                text: '["' + 'x'.repeat(2000) + '"]' };
            for (const listener of worker.listeners.get('message') || []) listener({ data: response });
        });
    };
    let parseCalled = false;
    const originalParse = json.parse;
    json.parse = function(value, reviver) {
        parseCalled = true;
        return originalParse.call(this, value, reviver);
    };
    const usedBeforeUnexpectedRead = budget.usedBytes;
    await assert.rejects(store.read(0, 1), /exceeded its reserved read budget/);
    assert.equal(parseCalled, false, 'unexpected worker text is rejected before JSON.parse');
    assert.equal(budget.usedBytes, usedBeforeUnexpectedRead, 'an oversized worker response releases its reservation');
    json.parse = originalParse;

    await store.dispose();
    assert.equal(budget.usedBytes, 0);
});

test('windows retained from several spilled stores remain charged until explicitly released', async () => {
    const { api } = loadApi();
    const budget = api.createRowStoreBudget(40000);
    const stores = [];
    for (let index = 0; index < 3; index++) {
        const store = await api.createRowStore({ memoryBudget: budget, workerFactory: () => new MemoryWorker(),
            spillRowLimit: 0, storageTimeout: 20 });
        stores.push(store);
        await store.append([[{ kind: 'literal', value: String(index) + 'x'.repeat(1000) }]]);
    }
    for (let attempt = 0; stores.some(store => store.inMemory) && attempt < 40; attempt++) {
        await new Promise(resolve => setImmediate(resolve));
    }
    assert.ok(stores.every(store => !store.inMemory), 'all three stores spilled');
    const before = budget.usedBytes;
    const first = await stores[0].readOwned(0, 1);
    const afterFirst = budget.usedBytes;
    assert.ok(afterFirst > before, 'the first decoded window remains reserved');
    const second = await stores[1].readOwned(0, 1);
    assert.ok(budget.usedBytes > afterFirst, 'the second decoded window has its own reservation');
    assert.equal(first.rows[0][0].value.length, 1001);
    assert.equal(second.rows[0][0].value.length, 1001);
    await assert.rejects(stores[2].readOwned(0, 1), /budget|storage|memory/i,
        'a third live decoded window cannot exceed the shared retained budget');
    first.release();
    const third = await stores[2].readOwned(0, 1);
    assert.equal(third.rows[0][0].value.length, 1001);
    first.release();
    second.release();
    third.release();
    await Promise.all(stores.map(store => store.dispose()));
    assert.equal(budget.usedBytes, 0);
});

test('spilled partial and empty windows use their actual size for read reservations', async () => {
    const { api } = loadApi();
    const budget = api.createRowStoreBudget(40000);
    const store = await api.createRowStore({ memoryBudget: budget, workerFactory: () => new MemoryWorker(),
        spillRowLimit: 0, storageTimeout: 100 });
    await store.append([[{ kind: 'literal', value: 'last row' }]]);
    for (let attempt = 0; store.inMemory && attempt < 40; attempt++) await new Promise(resolve => setImmediate(resolve));
    assert.equal(store.inMemory, false);
    const partial = await store.readOwned(0, 100);
    assert.equal(partial.rows.length, 1);
    assert.equal(partial.rows[0][0].value, 'last row');
    partial.release();
    const empty = await store.readOwned(1, 100);
    assert.equal(empty.rows.length, 0);
    empty.release();
    assert.equal((await store.read(0, 100)).length, 1);
    await store.dispose();
    assert.equal(budget.usedBytes, 0);
});

test('an owned memory window stays reserved after its store spills and is disposed', async () => {
    const { api } = loadApi();
    const budget = api.createRowStoreBudget(40000);
    const store = await api.createRowStore({ memoryBudget: budget, workerFactory: () => new MemoryWorker(),
        spillRowLimit: 1, storageTimeout: 100 });
    await store.append([[{ kind: 'literal', value: 'a'.repeat(1000) }]]);
    const window = await store.readOwned(0, 1);
    await store.append([[{ kind: 'literal', value: 'b'.repeat(1000) }]]);
    for (let attempt = 0; store.inMemory && attempt < 40; attempt++) await new Promise(resolve => setImmediate(resolve));
    assert.equal(store.inMemory, false);
    await store.dispose();
    assert.ok(budget.usedBytes > 0, 'the consumer still holds the first window after store disposal');
    assert.equal(window.rows[0][0].value, 'a'.repeat(1000));
    window.release();
    assert.equal(budget.usedBytes, 0);
});

test('an owned read waiting for memory follows a spill without losing its reservation', async () => {
    const { api } = loadApi();
    const budget = api.createRowStoreBudget(40000);
    const store = await api.createRowStore({ memoryBudget: budget, workerFactory: () => new MemoryWorker(),
        storageTimeout: 100 });
    await store.append([[{ kind: 'literal', value: 'x'.repeat(1000) }]]);
    const blocker = budget.createReservation('retained');
    await blocker.grow(18000);
    const reading = store.readOwned(0, 1);
    for (let attempt = 0; store.inMemory && attempt < 40; attempt++) await new Promise(resolve => setImmediate(resolve));
    assert.equal(store.inMemory, false, 'reservation pressure moves the source to the worker');
    blocker.release();
    const window = await reading;
    assert.equal(window.rows[0][0].value, 'x'.repeat(1000));
    await store.dispose();
    assert.ok(budget.usedBytes > 0, 'the decoded worker window remains reserved');
    window.release();
    assert.equal(budget.usedBytes, 0);
});

test('disposing a store while an owned read waits releases the pending reservation', async () => {
    const { api } = loadApi();
    const budget = api.createRowStoreBudget(40000);
    const store = await api.createRowStore({ memoryBudget: budget, workerFactory: () => new UnavailableWorker(),
        storageTimeout: 100 });
    await store.append([[{ kind: 'literal', value: 'x'.repeat(1000) }]]);
    const blocker = budget.createReservation('retained');
    await blocker.grow(18000);
    const reading = store.readOwned(0, 1);
    await store.dispose();
    blocker.release();
    await assert.rejects(reading, /disposed/i);
    assert.equal(budget.usedBytes, 0);
});

class IdentityWorker {
    constructor() {
        this.keys = new Set();
        this.baselineRows = 0;
        this.messages = [];
        this.listeners = new Map();
    }
    addEventListener(type, listener) {
        this.listeners.set(type, [...(this.listeners.get(type) || []), listener]);
    }
    removeEventListener(type, listener) {
        this.listeners.set(type, (this.listeners.get(type) || []).filter(value => value !== listener));
    }
    postMessage(message) {
        this.messages.push(message);
        queueMicrotask(() => {
            const response = { requestId: message.requestId, ok: true, indexId: message.indexId };
            if (message.op === 'identity-add') {
                let addedBytes = 0;
                for (const key of message.keys) {
                    if (!this.keys.has(key)) {
                        this.keys.add(key);
                        addedBytes += key.length * 2 + 16;
                    }
                }
                this.baselineRows += message.keys.length;
                response.baselineRows = this.baselineRows;
                response.addedBytes = addedBytes;
            } else if (message.op === 'identity-filter') {
                response.unseen = message.keys.map((key, index) => this.keys.has(key) ? -1 : index)
                    .filter(index => index >= 0);
            } else if (message.op === 'identity-dispose') {
                this.keys.clear();
            }
            for (const listener of this.listeners.get('message') || []) listener({ data: response });
        });
    }
    terminate() {}
}

test('identity batches reserve serialized keys before constructing them and can retry smaller rows', async () => {
    let worker;
    const { api, json } = loadApi({ Worker: class extends IdentityWorker {
        constructor() { super(); worker = this; }
    } });
    const budget = api.createRowStoreBudget(10000);
    const index = await api.createRowIdentityIndex('server/repository', budget);
    const row = [{ kind: 'literal', value: 'x'.repeat(2500) }];
    const before = budget.usedBytes;
    const originalStringify = json.stringify;
    let identitySerializationStarted = false;
    json.stringify = function(value, replacer, space) {
        if (Array.isArray(value) && value[0] === 'literal') identitySerializationStarted = true;
        return originalStringify.call(this, value, replacer, space);
    };

    await assert.rejects(index.add([row]), /budget|memory/i);
    assert.equal(identitySerializationStarted, false,
        'an identity batch that cannot fit is rejected before key strings are built');
    assert.equal(worker.messages.some(message => message.op === 'identity-add'), false);
    assert.equal(budget.usedBytes, before, 'the rejected batch releases staging and index reservations');

    await index.add([[{ kind: 'iri', value: 'urn:small' }]]);
    assert.equal(worker.messages.filter(message => message.op === 'identity-add').length, 1,
        'a smaller retry still uses the same baseline index');
    await index.dispose();
    assert.equal(budget.usedBytes, 0);
});
